import numpy as np

def mae(fact, pred):
    return float(np.abs(fact - pred).mean())

def rmse(fact, pred):
    return float(np.sqrt(((fact - pred) ** 2).mean()))

def wape(fact, pred):
    return float(np.abs(fact - pred).sum() / fact.sum())

m = {"mae": round(mae(fact, pred), 3), "rmse": round(rmse(fact, pred), 3), "wape": round(wape(fact, pred), 3)}
print(m)

